import{_ as l,o as h,c,ah as g}from"./chunks/framework.BcMkjLiY.js";const p="/projects/TonyPi/en/latest/assets/image0.B96sEICN.webp",e="/projects/TonyPi/en/latest/assets/image0.B96sEICN.webp",o="/projects/TonyPi/en/latest/assets/image2.DkugwduZ.webp",r="/projects/TonyPi/en/latest/assets/image3.BEi8xD2d.webp",i="/projects/TonyPi/en/latest/assets/image4.C9Dwgu0G.webp",s="/projects/TonyPi/en/latest/assets/image5.kDJ5KpAm.webp",n="/projects/TonyPi/en/latest/assets/image6.CESFfumf.webp",a="/projects/TonyPi/en/latest/assets/image7.tC_DFrRo.webp",d="/projects/TonyPi/en/latest/assets/image10.DUK57ito.webp",u="/projects/TonyPi/en/latest/assets/image8.Mbooauh-.webp",m="/projects/TonyPi/en/latest/assets/image9.B0TZmWrR.webp",y="/projects/TonyPi/en/latest/assets/image2.BdLgWav6.webp",w="/projects/TonyPi/en/latest/assets/image3.WSq_8b77.webp",b="/projects/TonyPi/en/latest/assets/image4.CTJPThZU.webp",f="/projects/TonyPi/en/latest/assets/image5.Dp_-dBnl.webp",q=JSON.parse('{"title":"1. Getting Ready","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.getting_ready.md","filePath":"docs/1.getting_ready.md"}'),_={name:"docs/1.getting_ready.md"};function P(T,t,x,v,z,k){return h(),c("div",null,[...t[0]||(t[0]=[g('<h1 id="_1-getting-ready" tabindex="-1">1. Getting Ready <a class="header-anchor" href="#_1-getting-ready" aria-label="Permalink to &quot;1. Getting Ready&quot;">​</a></h1><h2 id="_1-1-tonypi-instruction" tabindex="-1">1.1 TonyPi Instruction <a class="header-anchor" href="#_1-1-tonypi-instruction" aria-label="Permalink to &quot;1.1 TonyPi Instruction&quot;">​</a></h2><p><strong>1.1.1 Introduction</strong></p><p>TonyPi intelligent visual humanoid robot uses Raspberry Pi as the central controller. The image processing library is OpenCV and the programming language is Python.</p><p>Equipped with a 2-DOF high-definition camera, TonyPi is able to realize facial recognition, Color recognition, Auto shooting, Vision line follow，Tag recognition and etc. In this robot platform, uses can learn robot vision, OpenCV, robot technology and other knowledge.</p><img loading="lazy" height="469" width="324" class="common_img" src="'+p+'" style="width:350px;"><p><strong>1.1.2 Usage Precautions</strong></p><p>(1) Please pay attention to the following points when using and storing this product:</p><p>(2) This product contains conductive components. Avoid contact with metal objects when powered on.</p><p>(3) After the robot is powered on, do not forcibly move the servo, as this may cause damage.</p><p>(4) If the robot runs for an extended period, the servos may become hot. Allow the robot to &quot;<strong>rest</strong>&quot; and wait for the servos to cool before resuming operation.</p><p>(5) Keep your face, glasses, and other body parts away from the robot while it is operating. Do not place fingers within the joint movement range to prevent injury. Also, be cautious of falls from high edges.</p><p>(6) The robot&#39;s servos are precision components and consumable parts. They may need replacement after long-term or intensive use.</p><p>(7) If the product will not be used for an extended period, fully charge the battery, remove it, and store it in a cool, dry place.</p><p><strong>1.1.3 Copyright Notice</strong></p><p>This manual is the property of Shenzhen Hiwonder Technology Co., Ltd. No organization or individual is permitted to reproduce, copy, translate, or distribute any content from this manual without authorization.</p><p>Any unauthorized use or infringement of this manual&#39;s copyright will be subject to legal action by our company.</p><p><strong>1.1.4 Disclaimer</strong></p><p>The product described in this manual (including hardware, software, etc.) is provided &quot;<strong>as is</strong>&quot;. Every effort has been made to ensure the accuracy of this manual, but we cannot guarantee it is completely free from errors or omissions. This document is regularly reviewed, and we welcome feedback for improvements.</p><p>Product features and specifications may change with version upgrades. For the latest product information, please contact customer service when placing your order.</p><p>Furthermore, unless explicitly stated by Hiwonder, we are not responsible for any losses resulting from product malfunctions or damage under extreme conditions outside of typical use cases.</p><h2 id="_1-2-package-list" tabindex="-1">1.2 Package List <a class="header-anchor" href="#_1-2-package-list" aria-label="Permalink to &quot;1.2 Package List&quot;">​</a></h2><p><strong>(1) Standard Kit</strong></p><table class="docutils-nobg" border="1" style="text-align:center;"><thead><tr><th style="text-align:center;">No.</th><th style="text-align:center;">Product Name</th><th style="text-align:center;">Quantity</th><th style="text-align:center;">Picture</th></tr></thead><tbody><tr><td>1</td><td>TonyPi(Ready to use)</td><td>1</td><td><img loading="lazy" height="469" width="324" src="'+e+'" style="width:250px;"></td></tr><tr><td>2</td><td>12.6V Lipo battery charger</td><td>1</td><td><img loading="lazy" height="492" width="714" src="'+o+'" style="width:180px;"></td></tr><tr><td>3</td><td>Balls</td><td>3</td><td><img loading="lazy" height="331" width="972" src="'+r+'" style="width:150px;"></td></tr><tr><td>4</td><td>Tags</td><td>3</td><td><img loading="lazy" height="300" width="912" src="'+i+'" style="width:150px;"></td></tr><tr><td>5</td><td>Card Reader</td><td>1</td><td><img loading="lazy" height="1000" width="502" src="'+s+'" style="width:40px;"></td></tr><tr><td>6</td><td>Screwdriver</td><td>1</td><td><img loading="lazy" height="228" width="1352" src="'+n+'" style="width:150px;"></td></tr><tr><td>7</td><td>Accessory Bag <br> (M2*4 Round head screw * 5<br>M2*6 round head screw * 5<br>M3*6 Black round head screw * 2<br>M2*5 Round head self-tapping screw * 5<br>M2*6 Round head self-tapping screw * 5<br>A3*5*7 Round head cross-recessed washer-equipped self-tapping screw * 2<br>M2 nut * 5<br>10cm 3pin wire * 1<br>20cm 3pin wire * 1<br>Main plastic steering wheel * 2<br>Auxiliary plastic steering wheel * 2)</td><td>1</td><td><img loading="lazy" height="1324" width="2470" src="'+a+'" style="width:270px;"></td></tr><tr><td>8</td><td>User Manual</td><td>1</td><td><img loading="lazy" height="716" width="528" src="'+d+'" style="width:270px;"></td></tr></tbody></table><p><strong>(2) Advanced Kit</strong></p><table class="docutils-nobg" border="1" style="text-align:center;"><thead><tr><th style="text-align:center;">No.</th><th style="text-align:center;">Product Name</th><th style="text-align:center;">Quantity</th><th style="text-align:center;">Picture</th></tr></thead><tbody><tr><td>1</td><td>TonyPi(Ready to use)</td><td>1</td><td><img loading="lazy" height="469" width="324" src="'+e+'" style="width:250px;"></td></tr><tr><td>2</td><td>12.6V Lipo battery charger</td><td>1</td><td><img loading="lazy" height="492" width="714" src="'+o+'" style="width:180px;"></td></tr><tr><td>3</td><td>Balls</td><td>3</td><td><img loading="lazy" height="331" width="972" src="'+r+'" style="width:150px;"></td></tr><tr><td>4</td><td>Tags</td><td>3</td><td><img loading="lazy" height="300" width="912" src="'+i+'" style="width:150px;"></td></tr><tr><td>5</td><td>Card Reader</td><td>1</td><td><img loading="lazy" height="1000" width="502" src="'+s+'" style="width:40px;"></td></tr><tr><td>6</td><td>Screwdriver</td><td>1</td><td><img loading="lazy" height="228" width="1352" src="'+n+'" style="width:150px;"></td></tr><tr><td>7</td><td>Sponge Cubes</td><td>3</td><td><img loading="lazy" height="788" width="2749" src="'+u+'" style="width:150px;"></td></tr><tr><td>8</td><td>Map</td><td>1</td><td><img loading="lazy" height="561" width="696" src="'+m+'" style="width:270px;"></td></tr><tr><td>9</td><td>Accessory Bag <br> (M2*4 Round head screw * 5<br>M2*6 round head screw * 5<br>M3*6 Black round head screw * 2<br>M2*5 Round head self-tapping screw * 5<br>M2*6 Round head self-tapping screw * 5<br>A3*5*7 Round head cross-recessed washer-equipped self-tapping screw * 2<br>M2 nut * 5<br>10cm 3pin wire * 1<br>20cm 3pin wire * 1<br>Main plastic steering wheel * 2<br>Auxiliary plastic steering wheel * 2)</td><td>1</td><td><img loading="lazy" height="1324" width="2470" src="'+a+'" style="width:270px;"></td></tr><tr><td>8</td><td>User Manual</td><td>1</td><td><img loading="lazy" height="716" width="528" src="'+d+'" style="width:270px;"></td></tr></tbody></table><h2 id="_1-3-charging-and-power-on-status-description" tabindex="-1">1.3 Charging and Power-On Status Description <a class="header-anchor" href="#_1-3-charging-and-power-on-status-description" aria-label="Permalink to &quot;1.3 Charging and Power-On Status Description&quot;">​</a></h2><p><strong>Lithium batteries must be disconnected during transportation. Therefore, users should first connect the battery connector cable upon receiving the robot, then charge it. Only after the charging process is complete can the robot be powered on for the first time.</strong></p><p><strong>1.3.1 Charging</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please check whether the connector cable is properly connected before charging. Connect the red wire to red one and the black wire to black before charging.</p></div><img loading="lazy" height="690" width="1000" class="common_img" src="'+y+'" style="width:500px;"><p>(1) Plug the end of the charger to the hole of the Raspberry Pi expansion board on the back as pictured:</p><img loading="lazy" height="287" width="1268" class="common_img" src="'+w+'" style="width:700px;"><p>(2) The charger indicator will turn green when not powered on, and turns red when powered on to indicate charging (charging time is approximately 3 hours). When the indicator changes from red to green, it means charging is complete. After charging is complete, please unplug the charger as soon as possible. Do not leave it charging continuously!</p><p><strong>1.3.2 Turn on TonyPi</strong></p><p>(1) Switch on Raspberry Pi expansion board on the back. The LED1 and LED2 of the Raspberry Pi will be on firstly and then the LED2 will flash every 2 seconds, which means the robot is turned on successfully.</p><p>The Raspberry Pi is a small minicomputer. It usually takes about 1 minute to boot up from the time it is Powered ON, which is normal and expected.</p><p>(2) After turning on, Raspberry Pi will emit a &quot;<strong>Di</strong>&quot; sound and will be in a AP hotspot mode and launch a Wi-Fi hotspot with a network named with the first letters &quot;<strong>HW</strong>&quot;.</p><img loading="lazy" height="348" width="723" class="common_img" src="'+b+'" style="width:500px;"><p><strong>1.3.3 Check Battery Level</strong></p><p>TonyPi is equipped with a voltage display module on its back, allowing users to observe the current battery level of the robot in real time as pictured:</p><img loading="lazy" height="442" width="928" src="'+f+'" class="common_img"><p>The operating voltage range of TonyPi is 9V to 12.6V. When the battery is fully charged, the voltage display module will show &quot;<strong>12.6</strong>&quot;. When the current voltage is less than 10V, please recharge the robot promptly.</p>',43)])])}const C=l(_,[["render",P]]);export{q as __pageData,C as default};
